export const ProviderLogo = ({ provider, size = 14 }: { provider: Provider; size?: number }) => {
  switch (provider) {
    case 'claude':
      return <ClaudeLogo size={size} />
    case 'openai':
      return <OpenAILogo size={size} />
    case 'gemini':
      return <GeminiLogo size={size} />
    case 'opencode':
      return <OpenCodeLogo size={size} />
    case 'copilot':
      return <CopilotLogo size={size} />
    case 'vibe':
      return <VibeLogo size={size} />
    case 'ollama':
      return <OllamaLogo size={size} />
    case 'kilo':
      return <KiloLogo size={size} />
    case 'openrouter':
      return <OpenRouterLogo size={size} />
  }
}

